/**
 * Gmail Node - Version 2.1
 * Discriminator: resource=thread, operation=get
 */


interface Credentials {
  googleApi: CredentialReference;
  gmailOAuth2: CredentialReference;
}

export type GmailV21ThreadGetParams = {
  resource: 'thread';
  operation: 'get';
  authentication?: 'oAuth2' | 'serviceAccount' | Expression<string>;
/**
 * The ID of the thread you are operating on
 */
    threadId: string | Expression<string>;
/**
 * Whether to return a simplified version of the response instead of the raw data
 * @builderHint Keep true by default. Both settings return the messages with the headers as flat keys: `From`, `To`, `Subject` and, when the message has them, `Cc` and `Bcc`. Both also return `snippet`, `labels`, `id` and `threadId`. True returns no message body. False also returns the Gmail API payload of each message. The body is in `payload.body.data` or in `payload.parts[].body.data`, encoded in base64url. In a nested multipart message the body is deeper: look through the nested `parts` until you find `body.data`. There is no `text` or `html` field, so decode the data in a Code node. Set false only when the workflow needs the message body or the attachments. False uses much more memory and often causes out-of-memory crashes.
 * @default true
 */
    simple?: boolean | Expression<boolean>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Whether to return only thread messages
     * @default true
     */
    returnOnlyMessages?: boolean | Expression<boolean>;
  };
};

